                            sha(stream.bytes.prefixBytes())));
        }
        List<Object> cryptoRows = new ArrayList<>();
        List<Object> ackRows = new ArrayList<>();
        for (int level = 0; level < 3; level++) {
            Store store = crypto[level];
            cryptoRows.add(
                    Main.object(
                            "level",
                            LVL[level],
                            "ranges",
                            store.ranges(),
                            "unique",
                            store.unique,
                            "prefix",
                            store.prefix(),
                            "sha256",
                            sha(store.prefixBytes())));
            Ledger ledger = acks[level];
            ackRows.add(
                    Main.object(
                            "level",
                            LVL[level],
                            "count",
                            ledger.count,
                            "intervals",
                            (long) ledger.map.size(),
                            "prefix",
                            ledger.prefix(),
                            "sha256",
                            sha(ledger.hashBytes()),
                            "ecn",
                            Arrays.asList(ecn[level][0], ecn[level][1], ecn[level][2])));
        }
        List<Object> epochRows = new ArrayList<>();
        for (Map.Entry<Long, long[]> entry : epochStats.entrySet()) {
            long[] stats = entry.getValue();
            epochRows.add(
                    Main.object(
                            "epoch",
                            entry.getKey(),
                            "min",
                            stats[0],
                            "max",
                            stats[1],
                            "count",
                            stats[2]));
        }
        List<Object> cidRows = new ArrayList<>();
        for (long sequence : peerActive) {
            PeerCid record = peerObserved.get(sequence);
            cidRows.add(Main.object("sequence", sequence, "id", Main.hex(record.cid), "token", Main.hex(record.token)));
        }
        List<Object> keyRows = new ArrayList<>();
        for (int level = 0; level < 3; level++) if (keys[level]) keyRows.add(LVL[level]);
        return Main.object(
                "packets",
                packetRows,
                "datagrams",
                datagramRows,
                "closed",
                closedRow,
                "keys",
                keyRows,
                "received",
                Main.object(
                        "I",
                        largest[0] < 0 ? null : largest[0],
                        "H",
                        largest[1] < 0 ? null : largest[1],
                        "A",
                        largest[2] < 0 ? null : largest[2]),
                "key_epoch",
                currentEpoch,
                "epochs",
                epochRows,
                "opened",
                Main.object("bidi", openedBidi, "uni", openedUni),
                "used",
                used,
                "send_max_data",
                sendMaxData,
                "send_max_streams",
                Main.object("bidi", sendMaxStreamsBidi, "uni", sendMaxStreamsUni),
                "streams",
                streamRows,
                "crypto",
                cryptoRows,
                "acknowledged",
                ackRows,
                "peer_cids",
                cidRows,
                "retire_prior_to",
                retireThreshold,
                "retired_local",
                retiredLocal.intervals());
    }
